#include <sstream>
#include <string>

template <typename... Ts>
std::string joined(const Ts&... values)
{
    std::ostringstream out{};
    ((out << values << ' '), ...);
    std::string text{ out.str() };
    if (!text.empty())
    {
        text.pop_back();
    }
    return text;
}

hints:
A `std::ostringstream` (from `<sstream>`, covered properly in lesson 10.05) works like `std::cout`, except that what you write collects in a string, which `.str()` hands back:

```cpp
std::ostringstream out{};
out << 42 << ' ' << "hi";
std::string text{ out.str() };   // "42 hi"
```

unitTests:
TEST("mixed types") { CHECK_EQ(joined(1, "two", 3.5), "1 two 3.5"); }
TEST("one and none") { CHECK_EQ(joined("solo"), "solo"); CHECK_EQ(joined(), ""); }
TEST("chars and strings") { CHECK_EQ(joined('a', std::string{ "bc" }, 'd'), "a bc d"); }

